package com.example.demo.service;

import com.example.demo.config.FeatureProperties;
import com.example.demo.entity.Customer;
import com.example.demo.repo.CustomerRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CustomerServiceTest {

    private CustomerRepository repository;
    private FeatureProperties featureProperties;
    private CustomerService service;

    @BeforeEach
    public void setUp() {
        repository = mock(CustomerRepository.class);
        featureProperties = new FeatureProperties();
        service = new CustomerService(repository, featureProperties);
    }

    @Test
    public void createDelegatesToRepository() {
        Customer input = new Customer("Alice", "alice@example.com");
        when(repository.save(any(Customer.class))).thenReturn(input);

        Customer result = service.create(input);

        assertEquals("Alice", result.getName());
    }

    @Test
    public void findAllReturnsRepositoryContents() {
        List<Customer> customers = Arrays.asList(
                new Customer("Alice", "alice@example.com"),
                new Customer("Bob", "bob@example.com"));
        when(repository.findAll()).thenReturn(customers);

        List<Customer> result = service.findAll();

        assertEquals(2, result.size());
    }

    @Test
    public void findByIdReturnsOptional() {
        Customer customer = new Customer("Alice", "alice@example.com");
        when(repository.findById(1L)).thenReturn(Optional.of(customer));

        Optional<Customer> result = service.findById(1L);

        assertTrue(result.isPresent());
        assertEquals("Alice", result.get().getName());
    }

    @Test
    public void greetUsesPrefixWhenEnabled() {
        featureProperties.setGreetingEnabled(true);
        featureProperties.setGreetingPrefix("Hi");
        Customer customer = new Customer("Alice", "alice@example.com");

        assertEquals("Hi, Alice!", service.greet(customer));
    }

    @Test
    public void greetReturnsEmptyWhenDisabled() {
        featureProperties.setGreetingEnabled(false);
        Customer customer = new Customer("Alice", "alice@example.com");

        assertEquals("", service.greet(customer));
    }
}
